GPU_MEM_SIZE = 80 # GB

# EVOLVE-BLOCK-START

def compute_model_placement(gpu_num, models):
    """
    Multi-start greedy placement: run the greedy (place each model on the
    GPU with the lowest current KVPR among GPUs that fit) under several
    model orderings, and return the placement with the lowest max KVPR.
    """
    def kvpr(w, f):
        return w / f if f > 0 else float('inf')

    def greedy(order):
        placement = {g: [] for g in range(gpu_num)}
        free = [GPU_MEM_SIZE] * gpu_num
        weight = [0.0] * gpu_num
        for m in order:
            best_idx, best_ratio = None, float('inf')
            for g in range(gpu_num):
                if m.model_size <= free[g] and free[g] > 0:
                    r = weight[g] / free[g]
                    if r < best_ratio:
                        best_ratio, best_idx = r, g
            if best_idx is None:
                return None
            placement[best_idx].append(m)
            weight[best_idx] += m.req_rate / m.slo
            free[best_idx] -= m.model_size
        return placement, free, weight

    def local_search(placement, free, weight):
        # Move models off the worst-KVPR GPU while it strictly lowers the max.
        improved = True
        while improved:
            improved = False
            worst = max(range(gpu_num), key=lambda g: kvpr(weight[g], free[g]))
            worst_val = kvpr(weight[worst], free[worst])
            for m in list(placement[worst]):
                sw = weight[worst] - m.req_rate / m.slo
                sf = free[worst] + m.model_size
                for g in range(gpu_num):
                    if g == worst or m.model_size > free[g]:
                        continue
                    dw = weight[g] + m.req_rate / m.slo
                    df = free[g] - m.model_size
                    if max(kvpr(dw, df), kvpr(sw, sf)) < worst_val:
                        placement[worst].remove(m)
                        placement[g].append(m)
                        weight[worst], free[worst] = sw, sf
                        weight[g], free[g] = dw, df
                        improved = True
                        break
                if improved:
                    break
        return placement, max(kvpr(weight[g], free[g]) for g in range(gpu_num))

    orders = [
        sorted(models, key=lambda m: m.req_rate / m.slo, reverse=True),
        sorted(models, key=lambda m: m.model_size, reverse=True),
        sorted(models, key=lambda m: (m.req_rate / m.slo) * m.model_size, reverse=True),
    ]

    best_placement, best_score = None, float('inf')
    for order in orders:
        res = greedy(order)
        if res is None:
            continue
        p, s = local_search(*res)
        if s < best_score:
            best_placement, best_score = p, s

    if best_placement is None:
        # Fallback: last-resort greedy ignoring fit check (may overcommit)
        best_placement, _ = greedy(sorted(models, key=lambda m: m.req_rate / m.slo, reverse=True))
        if best_placement is None:
            raise ValueError("Unable to place all models on the given GPUs.")

    return best_placement

# EVOLVE-BLOCK-END


if __name__ == "__main__":
    # Test the algorithm

    from evaluator import generate_test_gpu_models
    from evaluator import calculate_kvcache_pressure
    from evaluator import safe_float
    import numpy as np

    test_cases = generate_test_gpu_models()
    all_kvpr = []
    for i, (gpu_num, gpu_models) in enumerate(test_cases):

        results = compute_model_placement(gpu_num, gpu_models)
        max_kvpr = calculate_kvcache_pressure(results)
        all_kvpr.append(safe_float(max_kvpr))

    avg_kvpr = np.mean(all_kvpr)
    if avg_kvpr != 0:
        avg_kvpr = 1.0 / avg_kvpr


    print(f"Max KVPR: {avg_kvpr:.3f}")

